def shout_all(words):
    result = []
    for w in words:
        result.append(w.upper())
    return result

print(shout_all(["go", "team"]))

def longest_word(words):
    best = ""
    for word in words:
        if len(word) > len(best):
            best = word
    return best

print(longest_word(["cat", "elephant", "dog"]))

def shortest_word(words):
    best = words[0]
    for word in words:
        if len(word) < len(best):
            best = word
    return best

print(shortest_word(["kiwi", "fig", "watermelon"]))

